ALTER TABLE "recipe_import_jobs" ADD CONSTRAINT "recipe_import_jobs_error_code_check" CHECK ("recipe_import_jobs"."error_code" IS NULL OR "recipe_import_jobs"."error_code" IN ('IMPORT_INVALID_URL', 'IMPORT_UNSUPPORTED_SOURCE', 'IMPORT_SOURCE_UNAVAILABLE', 'IMPORT_RECIPE_NOT_FOUND', 'IMPORT_IMAGE_INVALID', 'PAYLOAD_TOO_LARGE', 'IMPORT_TIMED_OUT', 'IMPORT_FAILED', 'SERVICE_UNAVAILABLE'));